export class Scene {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    // Loaded scenes. Both valid as long as the scene.
    getSceneGraph(): SceneGraph {
        return new SceneGraph(Donut_GetSceneGraph(this.handle));
    }

    // InstanceData / GeometryData / MaterialConstants structured buffers; valid as long as the scene.
    getBuffer(which: SceneBuffer): Opaque {
        return Donut_GetSceneBuffer(this.handle, which);
    }

    // Geometries of a loaded scene, addressed by global geometry index (0 .. count - 1).
    getGeometryCount(): int {
        return Donut_GetSceneGeometryCount(this.handle);
    }

    // Animations, e.g. glTF skeletal ones. Durations in seconds; apply poses the nodes at `time`.
    getAnimationCount(): int {
        return Donut_GetSceneAnimationCount(this.handle);
    }

    getAnimationDuration(index: int): number {
        return Donut_GetSceneAnimationDuration(this.handle, index);
    }

    applyAnimation(index: int, time: number): void {
        Donut_ApplySceneAnimation(this.handle, index, time);
    }

    getInstanceCount(): int {
        return Donut_GetSceneInstanceCount(this.handle);
    }

    // A node's world-space position into dst (3 floats); 0 if there's no node at path ("/Emitter").
    getNodePosition(path: string, dst: Opaque): int {
        return Donut_GetSceneNodePosition(this.handle, path, dst);
    }
}

export class SceneGraph {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    getRootNode(): Node {
        return new Node(Donut_GetRootNode(this.handle));
    }

    // Directional light in a new node under parentNode, shining along dir; angularSize in degrees.
    // Returns the light, valid as long as the scene graph; refresh the graph before using it.
    addDirectionalLight(parentNode: Node, name: string, dirX: number, dirY: number, dirZ: number, angularSize: number, irradiance: number): Light {
        return new Light(Donut_AddDirectionalLight(this.handle, parentNode.handle, name, dirX, dirY, dirZ, angularSize, irradiance));
    }

    print(): void {
        Donut_PrintSceneGraph(this.handle);
    }

    // Scene graph queries; the handles are valid as long as the scene.
    getLightCount(): int {
        return Donut_GetSceneGraphLightCount(this.handle);
    }

    getLight(index: int): Light {
        return new Light(Donut_GetSceneGraphLight(this.handle, index));
    }

    getCameraCount(): int {
        return Donut_GetSceneGraphCameraCount(this.handle);
    }

    getCamera(index: int): SceneCamera {
        return new SceneCamera(Donut_GetSceneGraphCamera(this.handle, index));
    }

    getMaterialCount(): int {
        return Donut_GetSceneGraphMaterialCount(this.handle);
    }

    getMaterial(index: int): Material {
        return new Material(Donut_GetSceneGraphMaterial(this.handle, index));
    }

    getMeshInstanceCount(): int {
        return Donut_GetSceneGraphMeshInstanceCount(this.handle);
    }

    // The instance index (what material ID passes write) and node of the index-th mesh instance.
    getMeshInstanceIndex(index: int): int {
        return Donut_GetMeshInstanceIndex(this.handle, index);
    }

    getMeshInstanceNode(index: int): Node {
        return new Node(Donut_GetMeshInstanceNode(this.handle, index));
    }
}

