export class Camera {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    // First person cameras only.
    lookAt(posX: number, posY: number, posZ: number, targetX: number, targetY: number, targetZ: number): void {
        Donut_CameraLookAt(this.handle, posX, posY, posZ, targetX, targetY, targetZ);
    }

    thirdPersonSetTarget(x: number, y: number, z: number): void {
        Donut_ThirdPersonCameraSetTarget(this.handle, x, y, z);
    }

    thirdPersonSetDistance(distance: number): void {
        Donut_ThirdPersonCameraSetDistance(this.handle, distance);
    }

    // Radians.
    thirdPersonSetRotation(yaw: number, pitch: number): void {
        Donut_ThirdPersonCameraSetRotation(this.handle, yaw, pitch);
    }

    // Orbits the target from the position.
    thirdPersonLookAt(posX: number, posY: number, posZ: number, targetX: number, targetY: number, targetZ: number): void {
        Donut_ThirdPersonCameraLookAt(this.handle, posX, posY, posZ, targetX, targetY, targetZ);
    }

    // Every frame, after Donut_SetPlanarView of the view it renders.
    thirdPersonSetView(view: View): void {
        Donut_ThirdPersonCameraSetView(this.handle, view.handle);
    }

    // Forward / up directions: 3 floats into dst (Ref of a `let` f32 array element).
    getDirection(dst: Opaque): void {
        Donut_GetCameraDirection(this.handle, dst);
    }

    getUp(dst: Opaque): void {
        Donut_GetCameraUp(this.handle, dst);
    }

    // Units per second.
    setMoveSpeed(speed: number): void {
        Donut_CameraSetMoveSpeed(this.handle, speed);
    }

    // Forward the pass input callbacks' arguments to these.
    keyboardUpdate(key: int, scancode: int, action: int, mods: int): void {
        Donut_CameraKeyboardUpdate(this.handle, key, scancode, action, mods);
    }

    mousePosUpdate(x: number, y: number): void {
        Donut_CameraMousePosUpdate(this.handle, x, y);
    }

    mouseButtonUpdate(button: int, action: int, mods: int): void {
        Donut_CameraMouseButtonUpdate(this.handle, button, action, mods);
    }

    mouseScrollUpdate(xOffset: number, yOffset: number): void {
        Donut_CameraMouseScrollUpdate(this.handle, xOffset, yOffset);
    }

    animate(elapsedSeconds: number): void {
        Donut_CameraAnimate(this.handle, elapsedSeconds);
    }

    // World-to-view matrix into dst: Ref(arr[0]) of a `let` f32[16] array, row-major, row-vector
    // convention (as Donut_SetPlanarView takes it).
    getWorldToView(dst: Opaque): void {
        Donut_GetCameraWorldToView(this.handle, dst);
    }

    // First person cameras only.
    lookAtWithUp(posX: number, posY: number, posZ: number, targetX: number, targetY: number, targetZ: number, upX: number, upY: number, upZ: number): void {
        Donut_CameraLookAtWithUp(this.handle, posX, posY, posZ, targetX, targetY, targetZ, upX, upY, upZ);
    }

    // 3 floats into dst.
    getPosition(dst: Opaque): void {
        Donut_GetCameraPosition(this.handle, dst);
    }
}

export class View {
    readonly handle: Opaque;

    constructor(handle: Opaque | null) {
        this.handle = handle as Opaque;
    }

    // True if the function that returned it failed.
    isNull(): boolean {
        return !this.handle;
    }

    // Matrices: Ref(arr[0]) of `let` f32[16] arrays, row-major, row-vector convention (as the math
    // functions in the examples build them); viewport of width x height pixels.
    setPlanarView(viewMatrix: Opaque, projMatrix: Opaque, width: int, height: int): void {
        Donut_SetPlanarView(this.handle, viewMatrix, projMatrix, width, height);
    }

    fillPlanarViewConstants(dst: Opaque): void {
        Donut_FillPlanarViewConstants(this.handle, dst);
    }

    // Viewport, matrices and derived state, e.g. to keep the previous frame's view.
    copyPlanarView(srcView: View): void {
        Donut_CopyPlanarView(this.handle, srcView.handle);
    }

    // enabled != 0: the view's draws use the framebuffer's shading rate surface alone; 0: full rate.
    setVariableRateShading(enabled: int): void {
        Donut_SetViewVariableRateShading(this.handle, enabled);
    }

    // Donut_SetPlanarView with a sub-pixel projection jitter, in pixels.
    setPlanarViewJittered(viewMatrix: Opaque, projMatrix: Opaque, width: int, height: int, pixelOffsetX: number, pixelOffsetY: number): void {
        Donut_SetPlanarViewJittered(this.handle, viewMatrix, projMatrix, width, height, pixelOffsetX, pixelOffsetY);
    }

    // Left eye in the left half of width x height pixels, right eye in the right half.
    setStereoView(leftViewMatrix: Opaque, rightViewMatrix: Opaque, projMatrix: Opaque, width: int, height: int, pixelOffsetX: number, pixelOffsetY: number): void {
        Donut_SetStereoView(this.handle, leftViewMatrix, rightViewMatrix, projMatrix, width, height, pixelOffsetX, pixelOffsetY);
    }

    copyStereoView(srcView: View): void {
        Donut_CopyStereoView(this.handle, srcView.handle);
    }

    // The left eye's planar view, e.g. for Donut_ThirdPersonCameraSetView.
    getStereoLeftView(): View {
        return new View(Donut_GetStereoLeftView(this.handle));
    }
}

